window.B1 = [{"n": 1, "title": "Hello!", "sub": "Greetings · introductions · I’m / you’re", "setting": "It’s Monday morning. Leo and Sara meet a new student at school. Use the words in the box. Words: morning, name, I’m, meet, this, fine, later.", "lines": [{"who": "Leo", "parts": ["Good ", {"num": "1"}, {"gap": "m…"}, ", Sara!"]}, {"who": "Sara", "parts": ["Hi, Leo! How are you?"]}, {"who": "Leo", "parts": ["I’m ", {"num": "2"}, {"gap": "f…"}, ", thanks. And you?"]}, {"who": "Sara", "parts": ["Great! Leo, ", {"num": "3"}, {"gap": "t…"}, " is Camila. She’s new."]}, {"who": "Leo", "parts": ["Hi, Camila! ", {"num": "4"}, {"gap": "I…"}, "Leo. Nice to ", {"num": "5"}, {"gap": "m…"}, " you."]}, {"who": "Camila", "parts": ["Nice to meet you too! Sorry, what’s your ", {"num": "6"}, {"gap": "n…"}, " again?"]}, {"who": "Leo", "parts": ["Leo. L-E-O. Oh! The bell! See you ", {"num": "7"}, {"gap": "l…"}, "!"]}], "ansT": {"1": "morning", "2": "fine", "3": "this", "4": "I’m", "5": "meet", "6": "name", "7": "later"}, "after": "Listen again and check. Then act it out in groups of three. Change the names!", "pairs": ["💬 At the bus stop — 8 am. Say hello to a classmate. Ask how they are.", "💬 Online game — Meet a new player. Ask their name and say yours.", "💬 New student — Introduce a new student to your best friend."], "sound": ["Short forms: Say the short forms together, like one word:", "I’m /aɪm/ · you’re /jʊr/ · what’s /wʌts/", "Link the words: Nice to meet you → “nice-tuh-MEET-chu”", "Questions with What’s…? and How…? go down at the end ↘"], "rtitle": "New School, New Friends!", "rsub": "Camila, 14, writes about her first day", "paras": ["Hi! I’m Camila and I’m new at Liceo Colón in Santiago. On Monday, I’m nervous. Then a girl says, “Hi!", "I’m Sara. What’s your name?” She is very friendly. Sara says, “This is Leo.", "He’s my classmate.” Leo says, “Nice to meet you, Camila!” At 12 o’clock, Ms. Peña, our teacher, says, “Good afternoon, class!”", "After school, Sara and Leo say, “Bye, Camila! See you tomorrow!” Now I’m happy. I have two new friends!"], "pull": "Now I’m happy. I have two new friends!", "atitle": "Read and answer.", "qa": ["1. Who says “Hi! What’s your name?”", "2. What does Ms. Peña say at 12 o’clock?", "3. Who are Camila’s two new friends?"], "qb": ["4. Camila is new at school. ____", "5. Sara is Camila’s teacher. ____", "6. Leo is Sara’s classmate. ____", "7. At the end, Camila is sad. ____"], "ansR": {"1": "Sara", "2": "“Good afternoon, class!”", "3": "Sara and Leo", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Diego’s post in the class chat.", "meta": "Class 1B · English Squad · Diego", "model": "Hi, everyone! I’m Diego. My friends say “Dieguito” . I’m in Class 1B with you. This is my best friend, Mateo. Nice to meet you all! See you on Monday!", "useful": [["Start", "Hi, everyone! / Hello, class!"], ["Name", "I’m… / My name is…"], ["Friend", "This is my friend…"], ["Polite", "Nice to meet you all!"], ["End", "See you later! / Bye! 👋"]], "task_title": "Write a hello post for your class group chat", "task": "Write 25–40 words. Include:", "cells": ["1 · Greeting: Hi, everyone! / Good morning, class!", "2 · You: your name + a friend: This is…", "3 · Goodbye: Nice to meet you! See you…"]}}, {"n": 2, "title": "The Alphabet", "sub": "Letters · spelling · a / an", "setting": "Diego wants to join the school Gaming Club. Valeria writes his information. Words: spell, name, D-I-E-G-O, username, at, dot, welcome.", "lines": [{"who": "Valeria", "parts": ["Hi! What’s your ", {"num": "1"}, {"gap": "n…"}, "?"]}, {"who": "Diego", "parts": ["Diego Ruiz."]}, {"who": "Valeria", "parts": ["How do you ", {"num": "2"}, {"gap": "s…"}, " Diego?"]}, {"who": "Diego", "parts": [{"num": "3"}, {"gap": "D…"}, "."]}, {"who": "Valeria", "parts": ["Thanks. And what’s your ", {"num": "4"}, {"gap": "u…"}, " for the club?"]}, {"who": "Diego", "parts": ["It’s D_Gamer9. Capital D, underscore, G-A-M-E-R, nine."]}, {"who": "Valeria", "parts": ["And your email?"]}, {"who": "Diego", "parts": ["diego.ruiz ", {"num": "5"}, {"gap": "a…"}, "mail ", {"num": "6"}, {"gap": "d…"}, " com."]}, {"who": "Valeria", "parts": ["Perfect! ", {"num": "7"}, {"gap": "W…"}, " to the club, Diego!"]}], "ansT": {"1": "name", "2": "spell", "3": "D-I-E-G-O", "4": "username", "5": "at", "6": "dot", "7": "Welcome"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Library card — You want a library card. Spell your name and last name.", "💬 New game — Create a username. Spell it to a friend.", "💬 Send me a photo — Give your partner an email address. Spell it."], "sound": ["Tricky letters: These letters are different in Spanish!", "A /eɪ/ (“ei”) · E /iː/ (“i”) · I /aɪ/ (“ai”)", "G /dʒiː/ vs J /dʒeɪ/ · R /ɑːr/ · Y /waɪ/ · Z /ziː/", "Practice: G-I-R-L · J-E-A-N-S · Y-E-S"], "rtitle": "Meet the Gaming Club!", "rsub": "Four new members and their usernames", "paras": ["Diego — Username: D_Gamer9. That’s a capital D, underscore, G-A-M-E-R, nine. Favorite thing: a fast laptop.", "Valeria — Username: ValeMusic. V-A-L-E, M-U-S-I-C. I have headphones for every game!", "Mateo — Username: MateoPix. M-A-T-E-O, P-I-X. I love my camera and an old phone.", "⭐ Emma — Username: EmmaStar. E, double M, A, S-T-A-R. My name has a double M!"], "pull": "My name has a double M!", "atitle": "Read and answer.", "qa": ["1. Spell Valeria’s username.", "2. Who has a camera?", "3. What is special about Emma’s name?"], "qb": ["4. Diego’s username has a number. ____", "5. Valeria loves cameras. ____", "6. Mateo has an old phone. ____", "7. Emma’s name has a double L. ____"], "ansR": {"1": "V-A-L-E-M-U-S-I-C", "2": "Mateo", "3": "It has a double M.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Emma’s profile.", "meta": "⭐ School Club · New member · EmmaStar", "model": "Hi! I’m Emma. That’s E, double M, A. My username is EmmaStar. I have a laptop and an old camera. My email is emma.star at mail dot com. See you at the club! ⭐", "useful": [["Name", "I’m… That’s E-M-M-A."], ["Username", "My username is…"], ["Things", "I have a… / an…"], ["Email", "… at … dot com"]], "task_title": "Write your profile for a school club", "task": "Write 25–40 words. Include:", "cells": ["1 · You: name + how you spell it", "2 · Username: invent it and spell it", "3 · Things: I have a… / an…"]}}, {"n": 3, "title": "Numbers 1–100", "sub": "Numbers · How old…? · How many…?", "setting": "Mateo calls his friend Leo after the basketball game. Words: score, old, many, fifteen, points, number, eight.", "lines": [{"who": "Mateo", "parts": ["Hi, Leo! What’s the ", {"num": "1"}, {"gap": "s…"}, "?"]}, {"who": "Leo", "parts": ["We win! 62 to 55!"]}, {"who": "Mateo", "parts": ["Wow! How ", {"num": "2"}, {"gap": "m…"}, " points for you?"]}, {"who": "Leo", "parts": ["Twenty-one ", {"num": "3"}, {"gap": "p…"}, "!"]}, {"who": "Mateo", "parts": ["Cool! And the new player? How ", {"num": "4"}, {"gap": "o…"}, " is he?"]}, {"who": "Leo", "parts": ["He’s ", {"num": "5"}, {"gap": "f…"}, ". His name is Andrés."]}, {"who": "Mateo", "parts": ["What’s his phone ", {"num": "6"}, {"gap": "n…"}, "?"]}, {"who": "Leo", "parts": ["It’s 809-555-0 ", {"num": "7"}, {"gap": "e…"}, " 3-1."]}], "ansT": {"1": "score", "2": "many", "3": "points", "4": "old", "5": "fifteen", "6": "number", "7": "eight"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 New friend — Ask a new friend’s age and phone number.", "💬 Sports reporter — Ask about the score and the points of a player.", "💬 How many? — Ask how many students, chairs and windows there are in the class."], "sound": ["-teen or -ty?: The stress is different!", "thirTEEN 13 vs THIRty 30", "fourTEEN 14 vs FORty 40", "fifTEEN 15 vs FIFty 50", "American English: thirty sounds like “thirdy”."], "rtitle": "The Big Game!", "rsub": "Liceo Duarte vs. Liceo Mella", "paras": ["It’s Friday and it’s the big game: Liceo Duarte vs. Liceo Mella. There are five players on each team and one hundred fans in the gym!", "The final score is 62 to 55. Liceo Duarte wins! Leo is the star.", "He’s fourteen and he has twenty-one points. Andrés is fifteen. He’s new on the team and he has twelve points.", "Coach Ruiz says, “Great game, team! Thirty minutes of practice on Monday!” Next game: Saturday at 4:00."], "pull": "The final score is 62 to 55.", "atitle": "Read and answer.", "qa": ["1. How many fans are in the gym?", "2. How many points for Leo?", "3. When is the next game?"], "qb": ["4. There are six players on each team. ____", "5. Liceo Duarte wins the game. ____", "6. Leo is fifteen. ____", "7. Andrés has twelve points. ____"], "ansR": {"1": "one hundred", "2": "twenty-one", "3": "Saturday at 4:00", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read the profile of Valeria’s volleyball team.", "meta": "School website · Teams · The Blue Stars", "model": "We are the Blue Stars! There are twelve players on the team. I’m Valeria and I’m fourteen. Our coach is Ms. Díaz. Our best score is 25 to 10! Practice is two days a week. Phone number for new players: 809-555-0190.", "useful": [["Team", "We are the… / There are … players."], ["Age", "I’m… / Our captain is…"], ["Score", "Our best score is … to …"], ["Contact", "Phone number: …"]], "task_title": "Write a profile of your team, club or group", "task": "Write 30–50 words. Include:", "cells": ["1 · Team: name + how many players", "2 · People: you, your age, the coach", "3 · Numbers: best score, practice, phone"]}}, {"n": 4, "title": "I, You, He, She…", "sub": "Subject pronouns · verb be (+ − ?)", "setting": "Leo shows Camila a photo of his friends. Words: is, are, isn’t, he, she, they, Are.", "lines": [{"who": "Leo", "parts": ["Look! These ", {"num": "1"}, {"gap": "a…"}, " my friends from school."]}, {"who": "Camila", "parts": ["Cool! Who’s the boy with the cap?"]}, {"who": "Leo", "parts": ["That’s Mateo. ", {"num": "2"}, {"gap": "H…"}, " is really funny!"]}, {"who": "Camila", "parts": ["And who’s the girl? ", {"num": "3"}, {"gap": "I…"}, " she your sister?"]}, {"who": "Leo", "parts": ["No, she ", {"num": "4"}, {"gap": "i…"}, ". That’s Valeria. ", {"num": "5"}, {"gap": "S…"}, " is my classmate."]}, {"who": "Camila", "parts": ["Are they in the English club?"]}, {"who": "Leo", "parts": ["Yes, ", {"num": "6"}, {"gap": "t…"}, "are. And Diego ", {"num": "7"}, {"gap": "i…"}, " the club president!"]}], "ansT": {"1": "are", "2": "He", "3": "Is", "4": "isn’t", "5": "She", "6": "they", "7": "is"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 My photo — Show a photo (or draw one). Say who the people are and how they are.", "💬 Phone call — Call a friend. Ask: Are you OK? Are you busy? Are you at home?", "💬 Mystery person — Describe a famous person with he/she + be. Your partner guesses."], "sound": ["Contractions: Say the short forms! They sound natural", "he’s /hiːz/ · she’s /ʃiːz/ · it’s /ɪts/", "we’re /wɪr/ · they’re /ðer/ · isn’t /ˈɪzənt/ · aren’t /ɑːrnt/", "Yes/No questions go up at the end ↗ Are you ready?"], "rtitle": "The English Squad", "rsub": "Five friends, one English club", "paras": ["We are the English Squad! We’re five friends from Class 1B. Diego is the president.", "He’s fourteen and he’s very friendly. Valeria is the music girl. She’s funny, but she isn’t loud.", "Mateo and Leo are the video team. They’re cool and creative. Camila is new.", "She’s a bit shy, but she’s ready for the club! Our teacher, Ms. Peña, is the boss.", "Are you fourteen or fifteen? Are you a fan of English? You’re welcome in the squad!"], "pull": "You’re welcome in the squad!", "atitle": "Read and answer.", "qa": ["1. How old is Diego?", "2. Is Valeria loud?", "3. Who is the boss?"], "qb": ["4. There are five friends in the squad. ____", "5. Valeria is the president. ____", "6. Mateo and Leo are the video team. ____", "7. Camila isn’t shy. ____"], "ansR": {"1": "He’s fourteen.", "2": "No, she isn’t.", "3": "Ms. Peña", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Mateo’s post.", "meta": "Mateo · photo post · mateo_pix", "model": "This is my squad! I’m Mateo, the guy with the camera. Leo is my best friend. He’s funny and cool. Sara and Camila are in my class. They’re friendly. Camila isn’t shy now! We’re the best team!", "useful": [["Start", "This is my squad! / Meet my friends!"], ["People", "He’s… / She’s… / They’re…"], ["Negative", "She isn’t… / They aren’t…"], ["End", "We’re the best team!"]], "task_title": "Write a post about your squad", "task": "Write 30–50 words. Include:", "cells": ["1 · Photo: This is my squad!", "2 · Friends: 3 people + adjectives", "3 · All of you: We’re…"]}}, {"n": 5, "title": "Where Are You From?", "sub": "Countries · nationalities · personal information", "setting": "Sara meets Lucas at an international youth camp. Words: from, Where, Brazilian, city, address, email, Nice.", "lines": [{"who": "Sara", "parts": ["Hi! I’m Sara. Where are you ", {"num": "1"}, {"gap": "f…"}, "?"]}, {"who": "Lucas", "parts": ["I’m from Brazil. I’m ", {"num": "2"}, {"gap": "B…"}, ". And you?"]}, {"who": "Sara", "parts": ["I’m Dominican. I’m from Santiago."]}, {"who": "Lucas", "parts": ["Cool! Is Santiago a big ", {"num": "3"}, {"gap": "c…"}, "?"]}, {"who": "Sara", "parts": ["Yes, it is! ", {"num": "4"}, {"gap": "W…"}, " is your city?"]}, {"who": "Lucas", "parts": ["São Paulo. Hey, what’s your ", {"num": "5"}, {"gap": "e…"}, "? Let’s be friends!"]}, {"who": "Sara", "parts": ["It’s sara.gomez at mail dot com."]}, {"who": "Lucas", "parts": [{"num": "6"}, {"gap": "N…"}, " to meet you, Sara!"]}], "ansT": {"1": "from", "2": "Brazilian", "3": "city", "4": "Where", "5": "email", "6": "Nice"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 At the airport — Ask a tourist where they are from and their nationality.", "💬 Camp check-in — Ask for a new camper’s name, age, country and email.", "💬 Online friend — Meet an online friend. Ask about their city and country."], "sound": ["Word stress: Stress the big syllable!", "aMErican · doMInican · MEXican", "braZILian · japaNESE · SPANish", "-ese nationalities have stress at the end: JapaNESE, ChiNESE."], "rtitle": "One Camp, Many Countries", "rsub": "Teens from 5 countries meet in Jarabacoa", "paras": ["Welcome to Camp Jarabacoa! This summer, there are teens from five countries. Kenji is fifteen and he’s Japanese.", "He’s from Tokyo, a very big city. Lucas is Brazilian. He’s from São Paulo.", "Emma and Noah are American. They’re from Miami. Sara and Leo are Dominican.", "They’re from Santiago. Their first language isn’t the same, but their camp language is English! “Where are you from?” is the first question every day."], "pull": "Their camp language is English!", "atitle": "Read and answer.", "qa": ["1. Where is Lucas from?", "2. What nationality are Sara and Leo?", "3. What is the first question every day?"], "qb": ["4. There are teens from five countries. ____", "5. Kenji is Brazilian. ____", "6. Emma and Noah are from Miami. ____", "7. The camp is in Santiago. ____"], "ansR": {"1": "São Paulo, Brazil", "2": "Dominican", "3": "“Where are you from?”", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Lucas’s camp profile.", "meta": "Camp Jarabacoa · Profiles · Lucas Silva 🇧🇷", "model": "Hi! I’m Lucas. I’m fifteen and I’m Brazilian. I’m from São Paulo, a big city in Brazil. My first language is Portuguese. My email is lucas.s at mail dot com. My new friends are Dominican and Japanese!", "useful": [["Me", "I’m… I’m fourteen."], ["Place", "I’m from… It’s a big / small city."], ["Nationality", "I’m Dominican."], ["Contact", "My email is…"]], "task_title": "Write your profile for the camp website", "task": "Write 30–50 words. Include:", "cells": ["1 · You: name, age, nationality", "2 · Place: city + country", "3 · Contact: email + friends"]}}, {"n": 6, "title": "Family & Friends", "sub": "Family · my, your, his, her · ’s · Whose?", "setting": "Diego shows Mateo a family photo on his phone. Words: my, Her, his, Who’s, cousin, Whose, our.", "lines": [{"who": "Diego", "parts": ["Look! This is ", {"num": "1"}, {"gap": "m…"}, " family at my grandma’s house."]}, {"who": "Mateo", "parts": ["Nice! ", {"num": "2"}, {"gap": "W…"}, " that?"]}, {"who": "Diego", "parts": ["That’s my aunt Lucía. ", {"num": "3"}, {"gap": "H…"}, " house is in Puerto Plata."]}, {"who": "Mateo", "parts": ["And the boy with the ball?"]}, {"who": "Diego", "parts": ["That’s my ", {"num": "4"}, {"gap": "c…"}, "Andrés. He’s eleven. And that’s ", {"num": "5"}, {"gap": "h…"}, " dad, my uncle Tony."]}, {"who": "Mateo", "parts": [{"num": "6"}, {"gap": "W…"}, " dog is that?"]}, {"who": "Diego", "parts": ["It’s ", {"num": "7"}, {"gap": "o…"}, " dog, Coco! He’s part of the family."]}], "ansT": {"1": "my", "2": "Who’s", "3": "Her", "4": "cousin", "5": "his", "6": "Whose", "7": "our"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Family photo — Show a photo (or draw one). Introduce 4 people.", "💬 Birthday party — Introduce your cousin to your best friend.", "💬 Lost and found — Find the owner: Whose bag / phone / cap is this?"], "sound": ["’s sounds: The ’s has 3 sounds!", "/s/ → Pat’s, Mike’s", "/z/ → Leo’s, Sara’s, mom’s", "/ɪz/ → Luis’s, George’s (extra syllable)", "Also: Who’s = Whose — same sound, different meaning!"], "rtitle": "Sunday at Grandma’s", "rsub": "Valeria writes about her big Dominican family", "paras": ["Every Sunday, my family is at my grandma Rosa’s house in Santo Domingo. It’s big and noisy! My grandma is seventy and her food is amazing.", "My grandpa’s name is Juan. His jokes are terrible, but we love them! My parents are there, and my little brother Samuel.", "He’s eight. My aunt Lucía and her husband are there too, with their kids. My cousin Andrés is my best friend.", "Our dog, Coco, is under the table. It’s our favorite day of the week!"], "pull": "It’s our favorite day of the week!", "atitle": "Read and answer.", "qa": ["1. What’s Valeria’s grandpa’s name?", "2. How old is Samuel?", "3. Who is Valeria’s best friend?"], "qb": ["4. The family is at Valeria’s house on Sundays. ____", "5. Valeria’s grandma is seventy. ____", "6. Samuel is Valeria’s cousin. ____", "7. Coco is the family dog. ____"], "ansR": {"1": "Juan", "2": "He’s eight.", "3": "Her cousin Andrés", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s family poster.", "meta": "Class 1B · Family poster · Leo", "model": "This is my family! My mom’s name is Carmen. She’s a nurse. My dad’s name is Rafael. His favorite sport is baseball . My sister Ana is eleven. Her best friend is our cousin Mia. Our cat is Luna. I love my family!", "useful": [["Start", "This is my family! / There are five people in my family."], ["People", "My mom’s name is… She’s…"], ["Possessives", "his / her / our / their"], ["End", "I love my family!"]], "task_title": "Write about your family for a class poster", "task": "Write 35–50 words. Include:", "cells": ["1 · Who?: the people in your family", "2 · Details: names, ages, jobs, favorites", "3 · Pets & love: pets + final sentence"]}}, {"n": 7, "title": "Colors, Clothes & Style", "sub": "Colors · clothes · adjective + noun", "setting": "Camila and Sara choose clothes for the school photo day. Words: wear, color, blue, white, are, jacket, cool.", "lines": [{"who": "Camila", "parts": ["What do I ", {"num": "1"}, {"gap": "w…"}, " for photo day?"]}, {"who": "Sara", "parts": ["The uniform, but you can wear a ", {"num": "2"}, {"gap": "j…"}, " too."]}, {"who": "Camila", "parts": ["OK. What ", {"num": "3"}, {"gap": "c…"}, " is the school jacket?"]}, {"who": "Sara", "parts": ["It’s dark ", {"num": "4"}, {"gap": "b…"}, "with a ", {"num": "5"}, {"gap": "w…"}, " star."]}, {"who": "Camila", "parts": ["Nice! And my sneakers? They ", {"num": "6"}, {"gap": "a…"}, " pink."]}, {"who": "Sara", "parts": ["Pink sneakers are ", {"num": "7"}, {"gap": "c…"}, "! Wear them!"]}], "ansT": {"1": "wear", "2": "jacket", "3": "color", "4": "blue", "5": "white", "6": "are", "7": "cool"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 At the store — You want a new hoodie. Say the color and size.", "💬 Photo day — Ask a friend what to wear. Give advice.", "💬 Lost clothes — Describe your lost jacket to the teacher."], "sound": ["/ʃ/ or /tʃ/?: Two different sounds!", "/ʃ/ shirt · shorts · shoes (like “shhh!” )", "/tʃ/ choose · cheap · watch (like “chévere”)", "Practice: She chooses short shirts."], "rtitle": "Uniform or Free Style?", "rsub": "Three students, three opinions", "paras": ["Leo, 14: I like the uniform. It’s easy! Every day I wear a light blue shirt and dark blue pants. No problems in the morning.", "Valeria, 15: Uniforms are boring. Free style is better! My favorite clothes are black jeans, a white T-shirt and a green jacket.", "Mateo, 14: Uniform, yes — but sneakers, free! My sneakers are red and white. They’re my style! On Fridays, students wear free clothes at our school. It’s the best day!"], "pull": "My sneakers are red and white. They’re my style!", "atitle": "Read and answer.", "qa": ["1. What color is Leo’s shirt?", "2. What are Valeria’s favorite clothes?", "3. Which day is the best for Mateo?"], "qb": ["4. Leo likes the uniform. ____", "5. Valeria’s favorite jacket is green. ____", "6. Mateo’s sneakers are black. ____", "7. Students wear free clothes on Mondays. ____"], "ansR": {"1": "light blue", "2": "black jeans, a white T-shirt and a green jacket", "3": "Friday", "4": "T", "5": "T", "6": "F", "7": "F"}, "write": {"model_title": "Read Valeria’s style post.", "meta": "vale.music · style post · ValeMusic", "model": "My style? Simple and cool! My favorite clothes are black jeans and a white T-shirt. My jacket is green. My sneakers are old, but I love them. For school, I wear a blue uniform. My favorite color is black!", "useful": [["Start", "My style? … / I love my…"], ["Clothes", "My favorite clothes are…"], ["Colors", "My jacket is… / They’re…"], ["School", "For school, I wear…"]], "task_title": "Write a post about your style", "task": "Write 30–50 words. Include:", "cells": ["1 · Style: one word: cool, sporty, simple…", "2 · Clothes: 3 clothes + colors", "3 · School: uniform? favorite color"]}}, {"n": 8, "title": "Body & Looks", "sub": "The body · have / has · describing people", "setting": "Diego asks Sara about the new player on the volleyball team. Words: look, tall, has, hair, have, doesn’t, eyes.", "lines": [{"who": "Diego", "parts": ["Who’s the new player? What does she ", {"num": "1"}, {"gap": "l…"}, " like?"]}, {"who": "Sara", "parts": ["She’s very ", {"num": "2"}, {"gap": "t…"}, " — 1.80 m!"]}, {"who": "Diego", "parts": ["Wow! Does she have long ", {"num": "3"}, {"gap": "h…"}, "?"]}, {"who": "Sara", "parts": ["Yes, she does. She ", {"num": "4"}, {"gap": "h…"}, "long curly hair and big brown ", {"num": "5"}, {"gap": "e…"}, "."]}, {"who": "Diego", "parts": ["Does she ", {"num": "6"}, {"gap": "h…"}, " glasses?"]}, {"who": "Sara", "parts": ["No, she ", {"num": "7"}, {"gap": "d…"}, ". Her name is Andrea. She’s really nice!"]}], "ansT": {"1": "look", "2": "tall", "3": "hair", "4": "has", "5": "eyes", "6": "have", "7": "doesn’t"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Lost friend — You can’t find your friend at the mall. Describe him/her to security.", "💬 Avatar — Create a game avatar. Describe the hair, eyes and clothes.", "💬 Famous face — Describe a famous athlete. Your partner guesses."], "sound": ["has /z/: has and does end in a /z/ sound, like a bee zzz", "has /hæz/ · does /dʌz/ · eyes /aɪz/ · ears /ɪrz/", "doesn’t = /ˈdʌzənt/ — two syllables!"], "rtitle": "Mystery Portraits", "rsub": "Students describe a classmate — can you guess?", "paras": ["Mystery person A: This person is tall and thin. He has short black hair and big brown eyes. He has glasses. He doesn’t have a cap today. He has a camera in his hand!", "Mystery person B: She isn’t very tall. She has long curly black hair and dark eyes. She doesn’t have glasses. She has headphones around her neck.", "Mystery person C: He’s short and strong. He has short brown hair and a big smile. He has a basketball under his arm and white sneakers."], "pull": "He has a camera in his hand!", "atitle": "Read and answer.", "qa": ["1. Who is person A? (clue: camera 📷)", "2. Who is person B? (clue: music 🎧)", "3. Who is person C? (clue: basketball 🏀)"], "qb": ["4. Person A has glasses. ____", "5. Person B has short hair. ____", "6. Person B has headphones. ____", "7. Person C is tall. ____"], "ansR": {"1": "Mateo", "2": "Valeria", "3": "Leo", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s “wanted” poster.", "meta": "⭐ Class 1B · Fun posters · WANTED: SARA!", "model": "This is my best friend Sara. She’s tall and she has long black hair. She has big brown eyes and a beautiful smile. She doesn’t have glasses. She always has a book in her hand! She’s funny and very friendly.", "useful": [["Who", "This is my best friend…"], ["Body", "He’s / She’s tall / short."], ["Hair & eyes", "She has long curly hair / brown eyes."], ["Personality", "He’s funny / friendly / cool."]], "task_title": "Write a “wanted” poster for your best friend", "task": "Write 30–50 words. Include:", "cells": ["1 · Who?: name + tall / short", "2 · Looks: hair, eyes, glasses", "3 · Personality: funny, friendly…"]}}, {"n": 9, "title": "Wild World", "sub": "Animals · plurals · There’s / it’s", "setting": "Leo visits an animal shelter with Valeria, a volunteer. Words: pets, puppies, kittens, has, are, fish, cute.", "lines": [{"who": "Leo", "parts": ["Wow! How many ", {"num": "1"}, {"gap": "p…"}, " are here?"]}, {"who": "Valeria", "parts": ["Twenty dogs, fifteen cats and some rabbits."]}, {"who": "Leo", "parts": ["Look at the little dogs! How many ", {"num": "2"}, {"gap": "p…"}, "?"]}, {"who": "Valeria", "parts": ["Five puppies and three ", {"num": "3"}, {"gap": "k…"}, "."]}, {"who": "Leo", "parts": ["They ", {"num": "4"}, {"gap": "a…"}, "so ", {"num": "5"}, {"gap": "c…"}, "! And that big dog?"]}, {"who": "Valeria", "parts": ["That’s Max. He ", {"num": "6"}, {"gap": "h…"}, " one brown ear and one white ear."]}, {"who": "Leo", "parts": ["And the aquarium?"]}, {"who": "Valeria", "parts": ["Ten ", {"num": "7"}, {"gap": "f…"}, ". No, not fishes!"]}], "ansT": {"1": "pets", "2": "puppies", "3": "kittens", "4": "are", "5": "cute", "6": "has", "7": "fish"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 New pet — You want a pet. Ask a friend: How many? What color? Big or small?", "💬 Farm visit — Describe the animals on a farm with numbers and plurals.", "💬 Zoo guide — You’re a zoo guide. Present 3 wild animals."], "sound": ["-s endings: Plural -s has 3 sounds!", "/s/ → cats · ducks", "/z/ → dogs · birds · cows", "/ɪz/ → foxes · horses (one more syllable!)"], "rtitle": "The Whales of Samaná", "rsub": "Every winter, giant visitors arrive", "paras": ["Every year, from January to March, humpback whales are in Samaná Bay. They come from the cold North Atlantic. There are about two thousand whales!", "A humpback whale is very big: it’s fifteen meters long. It has two long fins and a big tail. Whales aren’t fish.", "They are mammals, like dogs and people. Moms have babies in the warm water of Samaná. Tourists and students go on boats to see them.", "The whales jump and sing. It’s amazing!"], "pull": "The whales jump and sing. It’s amazing!", "atitle": "Read and answer.", "qa": ["1. How many whales are there?", "2. Where do they come from?", "3. What do the whales do?"], "qb": ["4. The whales are in Samaná from January to March. ____", "5. A humpback whale is five meters long. ____", "6. Whales are fish. ____", "7. The whales have babies in Samaná. ____"], "ansR": {"1": "about two thousand", "2": "the cold North Atlantic", "3": "They jump and sing.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Mateo’s fact file.", "meta": "Science project · Fact files · 🐢 The Hawksbill Turtle", "model": "Name: hawksbill turtle (carey) · Type: wild Where: Caribbean Sea This turtle is small and beautiful. It has a brown and yellow shell. It doesn’t have teeth. Turtles are in danger, so protect them!", "useful": [["Type", "pet / farm / wild animal"], ["Looks", "It’s big / small. It has…"], ["Facts", "It doesn’t have… / They are…"], ["Message", "Protect them! / I love them!"]], "task_title": "Write a fact file about your favorite animal", "task": "Write 30–50 words. Include:", "cells": ["1 · Name & type: name + pet / farm / wild", "2 · Looks: size, color, body", "3 · Fun fact ⭐: one amazing fact"]}}, {"n": 10, "title": "School Life", "sub": "Classroom objects · this, that, these, those · one / ones", "setting": "Camila is looking for her things at the school Lost and Found. Words: this, Those, ones, one, these, that, Whose.", "lines": [{"who": "Camila", "parts": ["Excuse me. Is ", {"num": "1"}, {"gap": "t…"}, " my calculator?"]}, {"who": "Mr. Lara", "parts": ["Is it black?"]}, {"who": "Camila", "parts": ["No, mine is a gray ", {"num": "2"}, {"gap": "o…"}, "."]}, {"who": "Mr. Lara", "parts": ["Here. And are ", {"num": "3"}, {"gap": "t…"}, " your headphones?"]}, {"who": "Camila", "parts": ["Yes! Thank you! And ", {"num": "4"}, {"gap": "t…"}, " sunglasses on the table?"]}, {"who": "Mr. Lara", "parts": [{"num": "5"}, {"gap": "T…"}, "are Leo’s. And this water bottle? ", {"num": "6"}, {"gap": "W…"}, " is it?"]}, {"who": "Camila", "parts": ["It’s Sara’s. The pink ", {"num": "7"}, {"gap": "o…"}, " are Sara’s too!"]}], "ansT": {"1": "this", "2": "one", "3": "these", "4": "that", "5": "Those", "6": "Whose", "7": "ones"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 School store — Buy school things. Point: “Can I see that one, please?”", "💬 New student — Show a new student the classroom: this is…, those are…", "💬 Lost and found — Find 3 lost objects. Ask: Whose… is this?"], "sound": ["/ð/ this: Put your tongue between your teeth for th:", "this · that · these · those · they", "Not “dis” or “dat”! Practice: This is that one, and these are those ones."], "rtitle": "What’s in My Backpack?", "rsub": "Diego shows his backpack to his followers", "paras": ["Hi, guys! Diego here. Today: what’s in my backpack? OK, this is my notebook for English.", "It’s blue, like my favorite team. These are my pens: a black one and two red ones. That’s my calculator — it’s old, but it’s my lucky one! These are my headphones.", "They’re for the bus. And this? It’s my water bottle. It’s green.", "Oh! What’s that? It’s a snack… from last week! Don’t do that, guys!"], "pull": "It’s old, but it’s my lucky one!", "atitle": "Read and answer.", "qa": ["1. What color are the two pens?", "2. What are the headphones for?", "3. What’s the surprise at the end?"], "qb": ["4. Diego’s English notebook is blue. ____", "5. He has three black pens. ____", "6. His calculator is new. ____", "7. His water bottle is green. ____"], "ansR": {"1": "red", "2": "for the bus", "3": "an old snack from last week", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Sara’s script.", "meta": "sara.reads · video script · Sara", "model": "Hi! I’m Sara. This is my backpack. It’s purple. These are my books — I love books! This is my pencil case. I have a yellow pencil and two blue ones. That’s my water bottle. And those are my headphones! Bye!", "useful": [["Start", "Hi, guys! Today: what’s in my backpack?"], ["Near", "This is my… / These are my…"], ["Far", "That’s my… / Those are…"], ["No repeat", "a red one · two blue ones"]], "task_title": "Write your own “What’s in my backpack?” script", "task": "Write 35–50 words. Include:", "cells": ["1 · Hello: name + backpack color", "2 · Objects: 4 objects with this / these", "3 · Surprise!: a funny last object"]}}, {"n": 11, "title": "My Space", "sub": "Rooms · furniture · there is / there are · prepositions of place", "setting": "Mateo can’t find his phone. His sister Lía helps him. Words: Where’s, on, there, under, next to, in, Is.", "lines": [{"who": "Mateo", "parts": ["Lía! ", {"num": "1"}, {"gap": "W…"}, " my phone?"]}, {"who": "Lía", "parts": ["Is it ", {"num": "2"}, {"gap": "o…"}, " your desk?"]}, {"who": "Mateo", "parts": ["No. ", {"num": "3"}, {"gap": "T…"}, " are books and a lamp, but no phone."]}, {"who": "Lía", "parts": [{"num": "4"}, {"gap": "I…"}, " it in the living room?"]}, {"who": "Mateo", "parts": ["No, I don’t think so."]}, {"who": "Lía", "parts": ["Look ", {"num": "5"}, {"gap": "u…"}, " the bed!"]}, {"who": "Mateo", "parts": ["Nothing… Oh wait! It’s ", {"num": "6"}, {"gap": "i…"}, "my backpack, ", {"num": "7"}, {"gap": "n…"}, " my headphones!"]}], "ansT": {"1": "Where’s", "2": "on", "3": "There", "4": "Is", "5": "under", "6": "in", "7": "next to"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 House for rent — Describe a house to a family: rooms, furniture.", "💬 Lost keys — Ask: Where are my keys? Your partner gives clues with prepositions.", "💬 Hotel room — Check into a hotel room. Ask: Is there a TV / Wi-Fi / a fridge?"], "sound": ["there’s /ðerz/: Link there + is → there’s /ðerz/", "Link there + are → there are /ðer ɑːr/", "Careful! there, their and they’re sound the same", "There’s their dog. They’re happy."], "rtitle": "Valeria’s Room Tour", "rsub": "“My room is small, but it’s my world!”", "paras": ["Welcome to my room tour! My room isn’t very big, but I love it. There’s a bed next to the window.", "On the bed, there are three pillows: pink, white and gray. There’s a desk with my laptop and a little lamp. Above the desk, there are four shelves with books and plants.", "There isn’t a TV in my room — but there’s a speaker for my music! Under the bed, there’s a box with old photos. And there’s Coco, my cousin’s dog, behind the door!"], "pull": "My room isn’t very big, but I love it.", "atitle": "Read and answer.", "qa": ["1. How many pillows are there?", "2. What’s under the bed?", "3. Where’s Coco?"], "qb": ["4. Valeria’s room is very big. ____", "5. The bed is next to the window. ____", "6. There’s a TV in her room. ____", "7. There are plants on the shelves. ____"], "ansR": {"1": "three", "2": "a box with old photos", "3": "behind the door", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s room tour.", "meta": "leo.plays · room tour · Leo", "model": "Welcome to my room! There’s a big bed and a desk next to the window. On the wall, there are two baseball posters. There isn’t a TV, but there’s a guitar behind the door. My sneakers are under the bed. It’s a small room, but it’s cool!", "useful": [["Start", "Welcome to my room!"], ["What", "There’s a… / There are two…"], ["Where", "on · in · under · next to · behind"], ["Opinion", "It’s small, but it’s cool!"]], "task_title": "Write a room tour script for your room", "task": "Write 35–50 words. Include:", "cells": ["1 · Welcome: big / small room?", "2 · Things: 4 things with there is / are", "3 · Where?: 3 prepositions + opinion"]}}, {"n": 12, "title": "Food and Drinks", "sub": "Food · like / likes · present simple · some / any", "setting": "Sara has breakfast at Camila’s house. Camila’s mom asks questions. Words: like, Do, some, any, doesn’t, love, likes.", "lines": [{"who": "Mrs. Gómez", "parts": ["Good morning, Sara! ", {"num": "1"}, {"gap": "D…"}, " you like mangú?"]}, {"who": "Sara", "parts": ["Yes! I ", {"num": "2"}, {"gap": "l…"}, " mangú!"]}, {"who": "Mrs. Gómez", "parts": ["Great! Do you want ", {"num": "3"}, {"gap": "s…"}, " eggs too?"]}, {"who": "Sara", "parts": ["Yes, please. And cheese, please."]}, {"who": "Camila", "parts": ["Mom, is there ", {"num": "4"}, {"gap": "a…"}, " juice?"]}, {"who": "Mrs. Gómez", "parts": ["Yes, there’s passion fruit juice. Camila ", {"num": "5"}, {"gap": "l…"}, " it a lot!"]}, {"who": "Sara", "parts": ["And your dad? Does he ", {"num": "6"}, {"gap": "l…"}, " mangú?"]}, {"who": "Camila", "parts": ["No, he ", {"num": "7"}, {"gap": "d…"}, "! He eats bread and coffee."]}], "ansT": {"1": "Do", "2": "love", "3": "some", "4": "any", "5": "likes", "6": "like", "7": "doesn’t"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Shopping list — Plan a party. Ask: Is there any…? We need some…", "💬 Dinner guest — Ask a guest what he/she likes and doesn’t like.", "💬 Food reporter — Interview a partner about his/her favorite food."], "sound": ["-s: /s/ /z/ /ɪz/: He / she / it verbs end in -s with 3 sounds", "/s/ → likes · eats", "/z/ → loves · plays", "/ɪz/ → watches · washes (extra syllable!)"], "rtitle": "What Does Class 1B Eat?", "rsub": "Our food survey — 30 students", "paras": ["We have the results of our food survey! Twenty-five students like rice and beans — it’s the number one food in Class 1B. Pizza is number two.", "Mangoes are the favorite fruit, but four students don’t like them. Diego doesn’t like fish at all! Most students drink juice or water for lunch, and only five students drink soda.", "Leo likes salad — he’s an athlete! And Ms. Peña?", "She loves coffee. Healthy tip: eat some fruit every day!"], "pull": "Eat some fruit every day!", "atitle": "Read and answer.", "qa": ["1. What’s number two?", "2. How many students drink soda?", "3. Why does Leo like salad?"], "qb": ["4. Rice and beans is the number one food. ____", "5. All the students like mangoes. ____", "6. Diego likes fish. ____", "7. Ms. Peña loves coffee. ____"], "ansR": {"1": "pizza", "2": "five", "3": "He’s an athlete.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Camila’s food post.", "meta": "cami.eats · food post · Camila", "model": "My favorite meal is breakfast! I love mangú with eggs and cheese. My mom likes coffee, but I don’t like it. I drink passion fruit juice. My brother doesn’t like mangú — he eats bread. There’s some fruit on the table every day. Yum!", "useful": [["Favorite", "My favorite meal / food is…"], ["Likes", "I love… / I don’t like…"], ["Others", "My mom likes… / He doesn’t like…"], ["Details", "There’s some… / I drink…"]], "task_title": "Write about your favorite meal", "task": "Write 35–50 words. Include:", "cells": ["1 · Meal: breakfast, lunch or dinner?", "2 · You: love / like / don’t like", "3 · Family: likes / doesn’t like"]}}, {"n": 13, "title": "Me, You, Him, Her…", "sub": "Object pronouns · music & fans", "setting": "Valeria has two tickets for a concert in Santo Domingo. Words: you, her, them, me, us, it, him.", "lines": [{"who": "Valeria", "parts": ["Camila! I have two tickets for the concert on Saturday. One is for ", {"num": "1"}, {"gap": "y…"}, "!"]}, {"who": "Camila", "parts": ["Really? Thank you! Who’s the singer?"]}, {"who": "Valeria", "parts": ["Natti Natasha! Do you like ", {"num": "2"}, {"gap": "h…"}, "?"]}, {"who": "Camila", "parts": ["I love ", {"num": "3"}, {"gap": "h…"}, "! Her new song is amazing."]}, {"who": "Valeria", "parts": ["Yes! I listen to ", {"num": "4"}, {"gap": "i…"}, " every morning."]}, {"who": "Camila", "parts": ["Is Diego coming with ", {"num": "5"}, {"gap": "u…"}, "?"]}, {"who": "Valeria", "parts": ["No, he isn’t. He doesn’t like reggaeton. Text ", {"num": "6"}, {"gap": "h…"}, " — maybe he wants to come next time."]}, {"who": "Camila", "parts": ["OK. And the band before the singer? Do you know ", {"num": "7"}, {"gap": "t…"}, "?"]}], "ansT": {"1": "you", "2": "her", "3": "her", "4": "it", "5": "us", "6": "him", "7": "them"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Concert invitation — Invite a friend to a concert. Say: This ticket is for you!", "💬 Playlist — Make a 3-song playlist with a partner. Agree: I like it! / I don’t like it.", "💬 Fan interview — Interview a fan: Who’s your favorite singer? Why do you like him / her?"], "sound": ["Weak forms: Object pronouns are short and soft in fast English", "Call him → “CALL-im” · Love her → “LUV-er”", "Tell them → “TELL-em”", "Stress the verb, not the pronoun!"], "rtitle": "My Music, My Mood", "rsub": "Leo writes about the music he loves", "paras": ["Music is my life! I listen to it on the bus, in my room and at baseball practice. My favorite singer is Juan Luis Guerra.", "My parents love him too, and we sing his songs together in the car! My sister Ana likes K-pop. She has a poster of her favorite band in her room.", "She watches them on YouTube every day. My best friend Mateo plays the drums. I want a band with him and Diego.", "Our first song? It’s a secret. Don’t tell anybody!"], "pull": "We sing his songs together in the car!", "atitle": "Read and answer.", "qa": ["1. Where do Leo and his parents sing?", "2. How does Ana watch her favorite band?", "3. Who does Leo want a band with?"], "qb": ["4. Leo listens to music on the bus. ____", "5. Leo’s parents don’t like Juan Luis Guerra. ____", "6. Ana likes K-pop. ____", "7. Mateo plays the guitar. ____"], "ansR": {"1": "in the car", "2": "on YouTube", "3": "with Mateo and Diego", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s fan post.", "meta": "⭐ cami.eats · fan post · Camila", "model": "My favorite singer is Natti Natasha. She’s from Santiago, like me! I love her songs. I listen to them every day. My friend Valeria likes her too. On Saturday, we have tickets for her concert. Come with us!", "useful": [["Favorite", "My favorite singer / band is…"], ["Opinion", "I love him / her / them!"], ["When", "I listen to them every day / on the bus."], ["End", "Come with us! / Listen to them!"]], "task_title": "Write a fan post about your favorite singer or band", "task": "Write 35–50 words. Include:", "cells": ["1 · Artist: name, country", "2 · Why?: I love him / her because…", "3 · When & who: when you listen, friends who like it"]}}, {"n": 14, "title": "At the Café", "sub": "I’d like · Would you like…? · a / an / the · How much?", "setting": "Diego and Sara are at Café Colón after school. Words: would, I’d, a, the, How much, please, have.", "lines": [{"who": "Waiter", "parts": ["Hi! What ", {"num": "1"}, {"gap": "w…"}, " you like?"]}, {"who": "Sara", "parts": [{"num": "2"}, {"gap": "I…"}, " like a chicken salad and a mango smoothie, please."]}, {"who": "Waiter", "parts": ["And for you?"]}, {"who": "Diego", "parts": ["Can I ", {"num": "3"}, {"gap": "h…"}, "a burger and fries, ", {"num": "4"}, {"gap": "p…"}, "?"]}, {"who": "Waiter", "parts": ["Sure! Would you like ", {"num": "5"}, {"gap": "a…"}, " drink?"]}, {"who": "Diego", "parts": ["Yes, a soda, please. ", {"num": "6"}, {"gap": "H…"}, " is it?"]}, {"who": "Waiter", "parts": ["It’s 625 pesos. ", {"num": "7"}, {"gap": "T…"}, " smoothies are 2 for 1 today!"]}, {"who": "Sara", "parts": ["Great! Two smoothies, then!"]}], "ansT": {"1": "would", "2": "I’d", "3": "have", "4": "please", "5": "a", "6": "How much", "7": "The"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Fast food — Order a meal for you and a friend. Ask the total price.", "💬 Birthday treat — Order a cake for a friend’s birthday. Ask: How much is it?", "💬 Healthy menu — You don’t like fried food. Ask the waiter: Would you like…? Is there any…?"], "sound": ["I’d like /aɪd laɪk/: Link the words like one: I’d like · Would you → “wu-joo”", "Polite intonation goes up and down ↗↘: Would you like a drink?", "Numbers! fifTEEN vs FIFty pesos (Unit 3)"], "rtitle": "Café Colón: 5 Stars?", "rsub": "Sara and Diego review their favorite café", "paras": ["Café Colón is a small café next to our school. It’s our favorite place! The menu is short, but the food is great.", "The chicken sandwich is only 200 pesos and it’s delicious. The fries are crispy. The mango smoothie is the best in Santiago — and on Fridays smoothies are 2 for 1!", "The waiters are young and friendly. The only problem? The café is always full at 1:00.", "Our tip: say “I’d like…” and “please” — the waiters love it! Our score: ⭐⭐⭐⭐ (4/5)."], "pull": "The mango smoothie is the best in Santiago!", "atitle": "Read and answer.", "qa": ["1. What’s the best thing on the menu?", "2. What are the waiters like?", "3. What’s their score?"], "qb": ["4. Café Colón is next to the school. ____", "5. The chicken sandwich is 300 pesos. ____", "6. Smoothies are 2 for 1 on Fridays. ____", "7. The café is empty at 1:00. ____"], "ansR": {"1": "the mango smoothie", "2": "young and friendly", "3": "four stars (4/5)", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Mateo’s review.", "meta": "⭐ Food app · Reviews · mateo_pix · ⭐⭐⭐⭐⭐", "model": "The Pizza Corner is my favorite place! I always order a pepperoni pizza and an orange juice. The pizza is big and hot. It’s 350 pesos. The waiters are friendly. Tip: try the chocolate ice cream! 5 stars!", "useful": [["Place", "… is my favorite place / café."], ["Order", "I always order… / I’d like to try…"], ["Price", "It’s … pesos. / It isn’t expensive."], ["Score", "Tip: try the… · 4 stars!"]], "task_title": "Write a review of your favorite café or restaurant", "task": "Write 35–50 words. Include:", "cells": ["1 · Place: name + where", "2 · Food: what you order + price", "3 · Score ⭐: people, tip, stars"]}}, {"n": 15, "title": "Days, Months and Time", "sub": "Days · months · seasons · telling the time · in / on / at", "setting": "Leo calls Camila. They want to go to the movies. Words: time, on, at, half, Saturday, in, quarter.", "lines": [{"who": "Leo", "parts": ["Hi, Camila! Are you free ", {"num": "1"}, {"gap": "o…"}, " Saturday?"]}, {"who": "Camila", "parts": ["In the morning, no. I have dance class ", {"num": "2"}, {"gap": "i…"}, " the morning."]}, {"who": "Leo", "parts": ["And in the afternoon? There’s a movie ", {"num": "3"}, {"gap": "a…"}, " 4:00."]}, {"who": "Camila", "parts": ["OK! What ", {"num": "4"}, {"gap": "t…"}, " is it now?"]}, {"who": "Leo", "parts": ["It’s ", {"num": "5"}, {"gap": "h…"}, " past six."]}, {"who": "Camila", "parts": ["Let’s meet at ", {"num": "6"}, {"gap": "q…"}, " to four, at the mall."]}, {"who": "Leo", "parts": ["Perfect! See you on ", {"num": "7"}, {"gap": "S…"}, "!"]}], "ansT": {"1": "on", "2": "in", "3": "at", "4": "time", "5": "half", "6": "quarter", "7": "Saturday"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Movie plan — Invite a friend to a movie. Agree on day and time.", "💬 Appointment — Call a dentist. Ask for a day and time.", "💬 Practice schedule — Explain your team’s schedule: days and times."], "sound": ["Days: Stress the first syllable", "MONday · TUESday · WEDNESday /ˈwenzdeɪ/ · THURSday", "Wednesday: the first d is silent! “WENZ-day”"], "rtitle": "Camila’s Busy Week", "rsub": "Dance, school, family and… sleep!", "paras": ["Monday & Wednesday: School from 7:30 to 1:00. English club at quarter past two.", "Tuesday & Thursday: Dance class at 4:00. I get home at half past six.", "Friday: Homework in the afternoon. Movie night with my family at 8:00!", "Saturday: Dance competition at 10:00 in the morning. Pizza with Sara and Leo at 1:00.", "Sunday: No alarm! Lunch at grandma’s at noon. My favorite day!"], "pull": "Sunday: no alarm! My favorite day!", "atitle": "Read and answer.", "qa": ["1. What time does school start?", "2. What’s at 1:00 on Saturday?", "3. Why is Sunday her favorite day?"], "qb": ["4. Camila has English club on Tuesday. ____", "5. Her dance class is at 4:00. ____", "6. Movie night is on Friday. ____", "7. The competition is in the afternoon. ____"], "ansR": {"1": "at 7:30", "2": "pizza with Sara and Leo", "3": "No alarm! / lunch at grandma’s", "4": "F", "5": "T", "6": "T", "7": "F"}, "write": {"model_title": "Read Diego’s week.", "meta": "Class blog · My week · Diego", "model": "My week is busy! On Monday and Wednesday, I have baseball practice at 3:30. On Tuesday, I have English club at quarter past two. On Friday, I play video games at night. My favorite day is Saturday. I sleep in the morning!", "useful": [["Start", "My week is busy / relaxed!"], ["Days", "On Monday… / On weekends…"], ["Times", "at 3:30 · at night · in the morning"], ["Favorite", "My favorite day is… because…"]], "task_title": "Write about your week for the class blog", "task": "Write 35–50 words. Include:", "cells": ["1 · Busy?: busy or relaxed week?", "2 · Days & times ⏰: 3 activities: day + time", "3 · Favorite: favorite day + why"]}}, {"n": 16, "title": "First, Second, Third!", "sub": "Ordinal numbers · dates · birthdays · When…?", "setting": "Sara and Mateo plan a surprise party for Diego. Words: When, on, 15th, first, second, third, date.", "lines": [{"who": "Sara", "parts": [{"num": "1"}, {"gap": "W…"}, " is Diego’s birthday?"]}, {"who": "Mateo", "parts": ["It’s ", {"num": "2"}, {"gap": "o…"}, "March 15th. He’s fifteen on the ", {"num": "3"}, {"gap": "1…"}, "!"]}, {"who": "Sara", "parts": ["What’s the ", {"num": "4"}, {"gap": "d…"}, " today?"]}, {"who": "Mateo", "parts": ["March 10th. We have five days!"]}, {"who": "Sara", "parts": ["OK. ", {"num": "5"}, {"gap": "F…"}, ", we buy a cake."]}, {"who": "Mateo", "parts": [{"num": "6"}, {"gap": "S…"}, ", we make an invitation. And ", {"num": "7"}, {"gap": "t…"}, ", we decorate the room!"]}, {"who": "Sara", "parts": ["Perfect! Shh… it’s a surprise!"]}], "ansT": {"1": "When", "2": "on", "3": "15th", "4": "date", "5": "First", "6": "Second", "7": "third"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Party planner — Plan a party with a partner: date, time, place.", "💬 Sports reporter — Report the results of a race: first, second, third…", "💬 Holidays — Ask: When is Independence Day in DR? (February 27th)"], "sound": ["/θ/ th: Tongue between your teeth + air — like a soft “s”:", "fourth · fifth · sixth · third · thirteenth", "Not “fourt” or “fift”! Practice: the fifth of the sixth month"], "rtitle": "Happy Birthday Around the World", "rsub": "How do teens celebrate?", "paras": ["Birthdays are special everywhere! In the Dominican Republic, there’s always a big cake and loud music. Families sing “Cumpleaños feliz” and dance merengue.", "In the USA, friends sing “Happy Birthday to You” and the birthday person makes a wish and blows out the candles. In Mexico, people break a piñata. In Japan, the 20th birthday is very important: it’s the first day as an adult.", "And your fifteenth birthday? In many Latin American countries, it’s a giant party called a quinceañera!"], "pull": "Birthdays are special everywhere!", "atitle": "Read and answer.", "qa": ["1. What do people sing in the USA?", "2. Which birthday is important in Japan?", "3. What’s a quinceañera?"], "qb": ["4. In the DR, families dance merengue at birthdays. ____", "5. In Mexico, people break a piñata. ____", "6. In Japan, the 15th birthday is very important. ____", "7. A quinceañera is a small party. ____"], "ansR": {"1": "“Happy Birthday to You”", "2": "the 20th", "3": "a giant party for a 15th birthday", "4": "T", "5": "T", "6": "F", "7": "F"}, "write": {"model_title": "Read Sara’s invitation.", "meta": "Invitation · 🎉 Diego’s Surprise Party!", "model": "Hi, friends! You’re invited to Diego’s surprise party! When: Saturday, March 15th, at 4:00 Where: Mateo’s house, 22 Duarte Street Bring: snacks and music! Diego is turning fifteen. It’s his fifteenth birthday! Shh… don’t tell him!", "useful": [["Start", "You’re invited to…!"], ["When", "on Saturday, March 15th, at 4:00"], ["Where", "at… / … Street"], ["Extra", "Bring… / Don’t tell…!"]], "task_title": "Write an invitation for a party", "task": "Write 30–45 words. Include:", "cells": ["1 · What?: birthday, surprise, end of year…", "2 · When & where: date with ordinal + time + place", "3 · Details: what to bring, dress code"]}}, {"n": 17, "title": "A Day in My Life", "sub": "Daily routines · present simple · adverbs of frequency", "setting": "Valeria interviews Leo for the school podcast about his day. Words: get up, What time, always, goes, does, never, usually.", "lines": [{"who": "Valeria", "parts": ["Leo, you’re a baseball player and a student! ", {"num": "1"}, {"gap": "W…"}, " do you get up?"]}, {"who": "Leo", "parts": ["I ", {"num": "2"}, {"gap": "g…"}, " at 5:30. Every day!"]}, {"who": "Valeria", "parts": ["Wow! Do you have breakfast?"]}, {"who": "Leo", "parts": ["Yes, I ", {"num": "3"}, {"gap": "a…"}, " have breakfast. Eggs and fruit."]}, {"who": "Valeria", "parts": ["And your brother? Does he go to practice too?"]}, {"who": "Leo", "parts": ["No, he doesn’t. He ", {"num": "4"}, {"gap": "g…"}, " to music class. He plays the drums!"]}, {"who": "Valeria", "parts": ["What do you do at night?"]}, {"who": "Leo", "parts": ["I ", {"num": "5"}, {"gap": "u…"}, "do homework at 7:00. I ", {"num": "6"}, {"gap": "n…"}, "play video games on school days. My mom ", {"num": "7"}, {"gap": "d…"}, " n’t let me!"]}], "ansT": {"1": "What time", "2": "get up", "3": "always", "4": "goes", "5": "usually", "6": "never", "7": "does"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Podcast — Interview a classmate about his/her day.", "💬 ⭐ Famous routine — Imagine the routine of a famous athlete or singer.", "💬 Weekday vs. weekend — Compare your Monday and your Saturday."], "sound": ["Sentence stress: Stress the important words", "I ALways GET up at SIX.", "She NEver EATS BREAKfast.", "Small words (I, at, a, the) are weak and fast."], "rtitle": "A Day with a Young Pitcher", "rsub": "Andrés, 16, plays for a baseball academy in San Pedro", "paras": ["Andrés is sixteen and he wants to play in the Major Leagues one day. He gets up at 5:00 every morning and he always has a big breakfast. At 6:30, he goes to the baseball academy.", "He practices for four hours! Then he has lunch and goes to school from 1:00 to 5:00. In the evening, he does his homework and studies English with an app — he wants to talk to American coaches.", "He never goes to bed after 10:00. On Sundays, he relaxes with his family. “It’s hard, but I love it!”"], "pull": "It’s hard, but I love it!", "atitle": "Read and answer.", "qa": ["1. What time does he go to the academy?", "2. Why does he study English?", "3. What does he do on Sundays?"], "qb": ["4. Andrés gets up at 5:00. ____", "5. He practices for two hours. ____", "6. He studies English with an app. ____", "7. He usually goes to bed at 11:00. ____"], "ansR": {"1": "at 6:30", "2": "to talk to American coaches", "3": "He relaxes with his family.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Camila’s routine.", "meta": "Class blog · A day in my life · Camila", "model": "I usually get up at 6:15. I take a shower and I always have breakfast with my mom. I go to school by bus at 7:00. After school, I often go to dance class. My brother does his homework at 4:00, but I do it at night. I never go to bed before 10:00!", "useful": [["Morning", "I get up at… I always…"], ["School", "I go to school by…"], ["Afternoon", "After school, I usually…"], ["Night", "I never go to bed before…"]], "task_title": "Write about your school day", "task": "Write 40–55 words. Include:", "cells": ["1 · Morning: get up, breakfast, school", "2 · Afternoon: after school, homework, sports", "3 · Night: TV, family, bed + adverbs"]}}, {"n": 18, "title": "Who? What? Where?", "sub": "Question words · questions with be and do / does", "setting": "Camila interviews the new student, Andrea, for the school podcast. Words: Where, Why, What, How, Who, When, do.", "lines": [{"who": "Camila", "parts": ["Welcome, Andrea! ", {"num": "1"}, {"gap": "W…"}, " are you from?"]}, {"who": "Andrea", "parts": ["I’m from La Romana."]}, {"who": "Camila", "parts": [{"num": "2"}, {"gap": "W…"}, " do you like our school?"]}, {"who": "Andrea", "parts": ["Because the people are friendly!"]}, {"who": "Camila", "parts": [{"num": "3"}, {"gap": "W…"}, " is your favorite subject?"]}, {"who": "Andrea", "parts": ["Science! I love the ocean."]}, {"who": "Camila", "parts": ["Cool! ", {"num": "4"}, {"gap": "H…"}, " do you go to school?"]}, {"who": "Andrea", "parts": ["By bike."]}, {"who": "Camila", "parts": [{"num": "5"}, {"gap": "W…"}, " is your best friend here?"]}, {"who": "Andrea", "parts": ["Sara! We’re on the volleyball team."]}, {"who": "Camila", "parts": [{"num": "6"}, {"gap": "W…"}, " is your next game?"]}, {"who": "Andrea", "parts": ["On Saturday. ", {"num": "7"}, {"gap": "D…"}, " you want to come?"]}], "ansT": {"1": "Where", "2": "Why", "3": "What", "4": "How", "5": "Who", "6": "When", "7": "Do"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Celebrity interview — Interview a famous person (your partner plays the role).", "💬 New student — Ask a new student 5 questions about his/her life.", "💬 Detective — Ask questions to find a missing object: Where… When… Who…?"], "sound": ["Wh- intonation: Wh- questions go DOWN at the end ↘", "Where do you LIVE? ↘", "Yes/No questions go UP ↗", "Do you live in SANtiago? ↗"], "rtitle": "Questions for an Ocean Hero", "rsub": "Dr. Paola Núñez protects coral reefs in Bayahíbe", "paras": ["Who are you? Where do you work? I’m Paola, a marine biologist. I’m twenty-eight. I work in Bayahíbe, on the coast, and in a big aquarium.", "What do you do? I study and protect coral reefs. Corals are animals, not plants!", "Why are reefs important? Because fish live there, and they protect the beach.", "How do you help them? We grow baby corals and put them in the ocean.", "What advice do you have for teens? Ask questions! And study science and English."], "pull": "Ask questions! And study science and English.", "atitle": "Read and answer.", "qa": ["1. How old is Paola?", "2. Why are reefs important?", "3. What advice does she have?"], "qb": ["4. Paola is a marine biologist. ____", "5. She works in Santiago. ____", "6. Corals are plants. ____", "7. She grows baby corals. ____"], "ansR": {"1": "twenty-eight", "2": "because fish live there and they protect the beach", "3": "Ask questions; study science and English.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Diego’s interview with his grandpa.", "meta": "School project · Family heroes · Diego interviews Grandpa Juan", "model": "Where are you from? — I’m from Moca. What do you do? — I’m a farmer. I grow cacao. When do you get up? — At 5:00, every day! Why do you like your job? — Because I love nature. How do you relax? — I play dominoes!", "useful": [["Person", "Who…? What do you do?"], ["Place & time", "Where…? When…? What time…?"], ["Reasons", "Why…? — Because…"], ["Way", "How…? How often…?"]], "task_title": "Interview a family member or neighbor. Write 5 questions and answers", "task": "Write 5 Q + 5 A. Include:", "cells": ["1 · Choose: who you interview", "2 · Questions: 5 different question words", "3 · Answers: short, full sentences"]}}, {"n": 19, "title": "I Can Do It!", "sub": "can / can’t for ability · talents · well", "setting": "Mateo and Valeria organize the school talent show. Diego wants to participate. Words: can, can’t, Can, well, sing, play, a little.", "lines": [{"who": "Mateo", "parts": ["Hi, Diego! What ", {"num": "1"}, {"gap": "c…"}, " you do?"]}, {"who": "Diego", "parts": ["I can ", {"num": "2"}, {"gap": "p…"}, " the guitar."]}, {"who": "Valeria", "parts": ["Great! ", {"num": "3"}, {"gap": "C…"}, " you sing too?"]}, {"who": "Diego", "parts": ["Hmm… I can sing ", {"num": "4"}, {"gap": "a…"}, ", but not very ", {"num": "5"}, {"gap": "w…"}, "."]}, {"who": "Mateo", "parts": ["No problem! Valeria can ", {"num": "6"}, {"gap": "s…"}, ". She’s amazing!"]}, {"who": "Valeria", "parts": ["Let’s do a song together! But I ", {"num": "7"}, {"gap": "c…"}, " play the guitar."]}, {"who": "Diego", "parts": ["Perfect team!"]}], "ansT": {"1": "can", "2": "play", "3": "Can", "4": "a little", "5": "well", "6": "sing", "7": "can’t"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Talent show — Audition for the talent show. Say what you can do and how well.", "💬 Summer job — Apply for a job at a camp. Say your skills: I can swim, cook…", "💬 Superhero — Create a superhero. Present his/her powers with can / can’t."], "sound": ["can /kən/ vs can’t /kænt/: In sentences, can is short and weak: I /kən/ swim.", "can’t is long and strong: I /kænt/ swim.", "Short answers are strong: Yes, I /kæn/!", "Listen for the vowel: “kn” = can · “KAANT” = can’t"], "rtitle": "Liceo’s Got Talent!", "rsub": "Meet the stars of this year’s show", "paras": ["Friday’s talent show is a big success! Valeria and Diego open the show. She can sing very well and he can play the guitar.", "Then Andrés, a basketball player, juggles five balls — wow! Sara can’t sing or dance, but she can read poems in English and Spanish. Everybody claps!", "Mateo can’t perform, so he takes the photos and videos. The last act is Ms. Peña.", "Can teachers dance? Yes, they can! She dances bachata with the music teacher.", "The winner? Everybody!"], "pull": "Can teachers dance? Yes, they can!", "atitle": "Read and answer.", "qa": ["1. What can Diego do?", "2. What can Sara do?", "3. Why does Mateo take photos?"], "qb": ["4. Valeria can sing very well. ____", "5. Andrés juggles three balls. ____", "6. Sara can sing and dance. ____", "7. Ms. Peña dances bachata. ____"], "ansR": {"1": "play the guitar", "2": "read poems in English and Spanish", "3": "because he can’t perform", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Andrés’s profile.", "meta": "⭐ Talent show · Program · Andrés · The Juggler 🤹", "model": "Hi! I’m Andrés. I’m fifteen. I can play basketball very well and I can juggle five balls! I can speak English a little. But I can’t sing at all! My dream? I want to juggle on TV one day.", "useful": [["Intro", "Hi! I’m… I’m fifteen."], ["Talents", "I can… very well / well."], ["Honest!", "I can’t… at all! 😂"], ["Dream", "My dream? I want to…"]], "task_title": "Write your talent profile", "task": "Write 35–50 words. Include:", "cells": ["1 · You: name + age", "2 · Talents ⭐: 2 things you can do + how well", "3 · Can’t + dream: 1 thing you can’t do + your dream"]}}, {"n": 20, "title": "Can I…? Could You…?", "sub": "Permission and requests · polite English", "setting": "Leo goes to the school library. He needs a book for a project. Words: Can, Could, May, Sure, sorry, please, Of course.", "lines": [{"who": "Leo", "parts": ["Excuse me. ", {"num": "1"}, {"gap": "M…"}, " I come in?"]}, {"who": "Librarian", "parts": ["Yes, come in!"]}, {"who": "Leo", "parts": [{"num": "2"}, {"gap": "C…"}, " you help me? I need a book about whales."]}, {"who": "Librarian", "parts": [{"num": "3"}, {"gap": "S…"}, "! It’s on that shelf."]}, {"who": "Leo", "parts": ["Can I take it home, ", {"num": "4"}, {"gap": "p…"}, "?"]}, {"who": "Librarian", "parts": ["Yes, for one week."]}, {"who": "Leo", "parts": [{"num": "5"}, {"gap": "C…"}, " I use a computer?"]}, {"who": "Librarian", "parts": ["I’m ", {"num": "6"}, {"gap": "s…"}, ", they’re all busy now. Come back in 10 minutes."]}, {"who": "Leo", "parts": [{"num": "7"}, {"gap": "C…"}, " you say the time again, please?"]}], "ansT": {"1": "May", "2": "Can / Could", "3": "Sure", "4": "please", "5": "Can", "6": "sorry", "7": "Could"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 At the doctor — Ask the receptionist: Can I…? Could you…?", "💬 On the plane — Ask the flight attendant for water and a blanket.", "💬 At a friend’s house — Ask permission to use the bathroom, the Wi-Fi, the TV."], "sound": ["Polite intonation: Polite requests go up ↗ and sound soft:", "Could you HELP me, please? ↗", "Flat intonation sounds rude! → Could you help me.", "Could you → “cou-jew” · Can I → “ca-nai”"], "rtitle": "Can I…? The Library Rules", "rsub": "Your questions about the new school library", "paras": ["Can I eat in the library? No, you can’t. Food stays outside! But you can bring water.", "Can I use my phone? Yes, you can — in silent mode . No calls, please.", "Can I take books home? Of course! You can take two books for one week.", "Could the library open on Saturdays? Sorry, it can’t. But it’s open Monday to Friday until 5:00.", "Can I use the computers? Sure! Ask Ms. Ramírez, the librarian. She can help you."], "pull": "Food stays outside! But you can bring water.", "atitle": "Read and answer.", "qa": ["1. Can students bring water?", "2. How long can you keep the books?", "3. Who can help with the computers?"], "qb": ["4. Students can eat in the library. ____", "5. Phones are OK in silent mode. ____", "6. Students can take three books. ____", "7. The library is open on Saturdays. ____"], "ansR": {"1": "Yes, they can.", "2": "one week", "3": "Ms. Ramírez, the librarian", "4": "F", "5": "T", "6": "F", "7": "F"}, "write": {"model_title": "Read Camila’s message to her teacher.", "meta": "To: Ms. Peña · Subject: Dance competition · Camila Gómez", "model": "Dear Ms. Peña, Good morning! I have a dance competition on Friday at 10:00. May I leave class at 9:00? Could you send me the homework, please? I can do it on Saturday. Thank you very much! Camila", "useful": [["Start", "Dear… / Good morning!"], ["Reason", "I have… on Friday."], ["Ask", "May I…? · Could you…, please?"], ["End", "Thank you very much! / Best, …"]], "task_title": "Write a polite message to a teacher, coach or neighbor", "task": "Write 35–50 words. Include:", "cells": ["1 · Hello: Dear… + greeting", "2 · Reason + ask: why + May I / Could you…?", "3 · Thanks: Thank you + your name"]}}, {"n": 21, "title": "Do It! Don’t Do It!", "sub": "Imperatives · Let’s… · directions · rules", "setting": "Two tourists ask Diego for directions in Puerto Plata. Words: Excuse me, Go, Turn, Don’t, next to, Let’s, Be.", "lines": [{"who": "Tourist", "parts": [{"num": "1"}, {"gap": "E…"}, ". Where’s Long Beach?"]}, {"who": "Diego", "parts": ["It’s easy! ", {"num": "2"}, {"gap": "G…"}, " straight on this street."]}, {"who": "Tourist", "parts": ["OK. And then?"]}, {"who": "Diego", "parts": [{"num": "3"}, {"gap": "T…"}, "right at the big church. The beach is ", {"num": "4"}, {"gap": "n…"}, " the fish restaurant."]}, {"who": "Tourist", "parts": ["Thank you! Can we swim there?"]}, {"who": "Diego", "parts": ["Yes, but ", {"num": "5"}, {"gap": "d…"}, "swim at the red flag. ", {"num": "6"}, {"gap": "B…"}, " careful!"]}, {"who": "Tourist", "parts": ["Thanks! ", {"num": "7"}, {"gap": "L…"}, " go, Mom!"]}], "ansT": {"1": "Excuse me", "2": "Go", "3": "Turn", "4": "next to", "5": "don’t", "6": "Be", "7": "Let’s"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Lost tourist — Give directions from the school to a place in your town.", "💬 Lifeguard — Give 4 safety rules for the beach.", "💬 Recipe — Give instructions to make a smoothie: First, cut…"], "sound": ["Strong verbs: In imperatives, stress the verb", "STOP! · LOOK at me! · TURN left.", "Don’t is also strong: DON’T run!", "Let’s /lets/ — one syllable!"], "rtitle": "Beach Safety: Do’s and Don’ts", "rsub": "Advice from Carlos, 22, lifeguard in Cabarete", "paras": ["Put on sunscreen. Put it on every two hours. The Caribbean sun is strong!", "Look at the flags. Green = OK. Yellow = be careful. Red = don’t swim!", "Don’t swim alone. Always swim with a friend, near the lifeguard.", "Drink water. Don’t drink soda all day. Water is better.", "Take your trash. Don’t leave plastic on the sand. Let’s keep our beaches clean!"], "pull": "Let’s keep our beaches clean!", "atitle": "Read and answer.", "qa": ["1. What does a green flag mean?", "2. What’s better than soda?", "3. Why is the Caribbean sun dangerous?"], "qb": ["4. Put on sunscreen every two hours. ____", "5. A yellow flag means “don’t swim”. ____", "6. Swim alone, far from the lifeguard. ____", "7. Don’t leave plastic on the sand. ____"], "ansR": {"1": "It’s OK to swim.", "2": "water", "3": "It’s strong.", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read the English Club poster.", "meta": "English Club · Our rules · The English Squad Rules ✨", "model": "1. Speak English all the time! 2. Don’t laugh at mistakes — mistakes help us learn. 3. Be on time. The club starts at 2:15. 4. Help your classmates. 5. Don’t use phones, except for the English app. Let’s have fun!", "useful": [["Do", "Speak… / Be… / Help…"], ["Don’t", "Don’t laugh… / Don’t use…"], ["Polite", "Please… / …, please."], ["End", "Let’s have fun! / Let’s learn together!"]], "task_title": "Write 6 rules for your class, team or home", "task": "Write 6 rules + Let’s…. Include:", "cells": ["1 · Place: class, team, home…", "2 · Rules: 3 do’s + 3 don’ts", "3 · Let’s: a positive final sentence"]}}, {"n": 22, "title": "On the Move", "sub": "Transport · How do you go…? · by / on foot · feelings", "setting": "Sara and Mateo talk about the school trip to Santo Domingo. Words: by, How, long, takes, excited, nervous, on.", "lines": [{"who": "Sara", "parts": ["The school trip is on Friday! I’m so ", {"num": "1"}, {"gap": "e…"}, "!"]}, {"who": "Mateo", "parts": ["Me too! ", {"num": "2"}, {"gap": "H…"}, " do we go?"]}, {"who": "Sara", "parts": [{"num": "3"}, {"gap": "B…"}, " bus, from school to Santo Domingo."]}, {"who": "Mateo", "parts": ["How ", {"num": "4"}, {"gap": "l…"}, " does it take?"]}, {"who": "Sara", "parts": ["It ", {"num": "5"}, {"gap": "t…"}, " about two hours."]}, {"who": "Mateo", "parts": ["And in the city? Do we walk?"]}, {"who": "Sara", "parts": ["We go by metro and then ", {"num": "6"}, {"gap": "o…"}, " foot to the Zona Colonial."]}, {"who": "Mateo", "parts": ["I’m a little ", {"num": "7"}, {"gap": "n…"}, ". It’s my first time on the metro!"]}], "ansT": {"1": "excited", "2": "How", "3": "By", "4": "long", "5": "takes", "6": "on", "7": "nervous"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Traffic jam — You’re late. Call a friend: where you are, how you feel.", "💬 Tourist info — A tourist asks how to go from the airport to the city.", "💬 Travel vlog — Present your journey to school as a mini video blog."], "sound": ["/b/ and /v/: Different sounds in English!", "/b/ lips together: bus · bike · boat", "/v/ top teeth on lip: van · travel · nervous", "Practice: Very big buses travel every evening."], "rtitle": "How Do You Get to School?", "rsub": "Three students, three journeys", "paras": ["Sara, Santo Domingo: I go by metro. It takes 25 minutes. I listen to music, so I feel relaxed. The metro is fast, but it’s full at 7:00!", "Andrea, La Romana: I ride my bike. It takes 10 minutes. I love it — I feel free and happy! But when it rains, my dad takes me by car.", "Diego, Santiago: I take two buses. It takes one hour! There’s a lot of traffic, so I often feel bored and tired. I do my homework on the bus."], "pull": "I ride my bike. I feel free and happy!", "atitle": "Read and answer.", "qa": ["1. How does Sara feel on the metro?", "2. What happens when it rains?", "3. What does Diego do on the bus?"], "qb": ["4. Sara goes to school by bus. ____", "5. Andrea’s journey takes 10 minutes. ____", "6. Andrea always rides her bike. ____", "7. Diego’s journey takes one hour. ____"], "ansR": {"1": "relaxed", "2": "Her dad takes her by car.", "3": "his homework", "4": "F", "5": "T", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s answer to the survey.", "meta": "School survey · My journey · Leo", "model": "I live near the school, so I go on foot. It takes 15 minutes. I walk with Camila and we talk in English! On rainy days, I go by motoconcho. I feel happy on the way, but on Mondays I’m tired.", "useful": [["How", "I go by… / on foot."], ["How long", "It takes … minutes."], ["With who", "I go with… / alone."], ["Feelings", "I feel… / I’m… because…"]], "task_title": "Write about your journey to school", "task": "Write 35–50 words. Include:", "cells": ["1 · Transport: by… / on foot", "2 · Time ⏱: It takes…", "3 · Feelings: how you feel + why"]}}, {"n": 23, "title": "What Are You Doing?", "sub": "Present continuous · now vs. every day", "setting": "It’s Saturday. Camila calls Leo. Words: doing, am, playing, are, Is, watching, cooking.", "lines": [{"who": "Camila", "parts": ["Hi, Leo! What are you ", {"num": "1"}, {"gap": "d…"}, "?"]}, {"who": "Leo", "parts": ["I’m at the park. I’m ", {"num": "2"}, {"gap": "p…"}, " soccer with Diego."]}, {"who": "Camila", "parts": ["Cool! ", {"num": "3"}, {"gap": "I…"}, " Mateo with you?"]}, {"who": "Leo", "parts": ["Yes! He’s taking photos, as usual. And you?"]}, {"who": "Camila", "parts": ["I’m at home. My mom is ", {"num": "4"}, {"gap": "c…"}, "sancocho and my dad is ", {"num": "5"}, {"gap": "w…"}, " baseball on TV."]}, {"who": "Leo", "parts": ["Yum! ", {"num": "6"}, {"gap": "A…"}, " you helping your mom?"]}, {"who": "Camila", "parts": ["Yes, I ", {"num": "7"}, {"gap": "a…"}, "! I’m cutting the vegetables. Come for lunch!"]}], "ansT": {"1": "doing", "2": "playing", "3": "Is", "4": "cooking", "5": "watching", "6": "Are", "7": "am"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Phone call — Call a friend. Ask what he/she is doing now. Describe what you’re doing.", "💬 Photo story — Describe a photo on your phone: who, where, what they’re doing.", "💬 Spy game — Describe what people in the class are doing right now. Others guess who."], "sound": ["-ing /ɪŋ/: The -ng sound is in the back of the mouth — don’t say a hard “g”!", "playing · dancing · singing /ˈsɪŋɪŋ/", "In fast speech: “What are you doing?” → “Whatcha doing?”"], "rtitle": "English Squad Chat 💬", "rsub": "What’s everybody doing on Saturday?", "paras": ["Diego 10:05: Morning, squad! What are you doing? I’m bored.", "Valeria 10:06: I’m practicing for the talent show. I’m singing in my room!", "Mateo 10:08: I’m at the park with Leo. He’s playing soccer and I’m taking photos, of course.", "Sara 10:10: I’m reading a new book. It’s about whales!", "Camila 10:12: I’m cooking with my mom. We always make sancocho on Saturdays! Come at 1:00!", "Diego 10:13: Sancocho?! I’m not bored now. I’m going!"], "pull": "I’m not bored now. I’m going!", "atitle": "Read and answer.", "qa": ["1. What is Valeria doing?", "2. What is Leo doing?", "3. Why isn’t Diego bored at the end?"], "qb": ["4. Diego is bored at the beginning. ____", "5. Valeria is reading a book. ____", "6. Mateo is taking photos at the park. ____", "7. Camila’s family makes sancocho every day. ____"], "ansR": {"1": "She’s practicing / singing for the talent show.", "2": "He’s playing soccer.", "3": "Because he’s going to eat sancocho at Camila’s.", "4": "T", "5": "F", "6": "T", "7": "F"}, "write": {"model_title": "Read Sara’s message from the beach.", "meta": "English Squad · group chat · Sara", "model": "Hi, squad! I’m sitting on the beach in Sosúa with my family. The sun is shining . My brother is swimming and my parents are eating fried fish. I’m not swimming — I’m reading my whale book! We usually come here in August. What are you doing?", "useful": [["Where", "I’m at… / I’m sitting in…"], ["Me", "I’m …-ing. I’m not …-ing."], ["Others", "My mom is… / My friends are…"], ["Question", "What are you doing?"]], "task_title": "Write a message to your group: what’s happening now?", "task": "Write 40–55 words. Include:", "cells": ["1 · Where: place + weather", "2 · Actions: 4 people + -ing", "3 · Habit + question: one “every…” sentence + question"]}}, {"n": 24, "title": "And, But, Because, So", "sub": "Connectors · opinions · final project", "setting": "The squad chooses a movie for Friday night at Mateo’s house. Words: or, because, but, so, think, too, and.", "lines": [{"who": "Mateo", "parts": ["Comedy ", {"num": "1"}, {"gap": "o…"}, " horror movie?"]}, {"who": "Valeria", "parts": ["Not horror! It’s ", {"num": "2"}, {"gap": "t…"}, " scary for me."]}, {"who": "Leo", "parts": ["I ", {"num": "3"}, {"gap": "t…"}, " action movies are the best. They’re exciting!"]}, {"who": "Mateo", "parts": ["OK, ", {"num": "4"}, {"gap": "b…"}, " Camila doesn’t like action movies."]}, {"who": "Valeria", "parts": ["Let’s watch a comedy ", {"num": "5"}, {"gap": "b…"}, " everybody likes comedies!"]}, {"who": "Leo", "parts": ["Fine. It’s a comedy, ", {"num": "6"}, {"gap": "s…"}, "I’m bringing popcorn ", {"num": "7"}, {"gap": "a…"}, " soda!"]}, {"who": "Mateo", "parts": ["Perfect! See you on Friday!"]}], "ansT": {"1": "or", "2": "too", "3": "think", "4": "but", "5": "because", "6": "so", "7": "and"}, "after": "Listen again and check. Then act it out with a partner.", "pairs": ["💬 Movie critic — Recommend a movie: what it’s about, why you like it.", "💬 Food fight — Pizza or mangú? Give 3 reasons with because.", "💬 Book review — Talk about your favorite unit in this book and why."], "sound": ["Linking: Connect the words — sound like a native!", "I like it and I love it → “I-lai-ki-tan-dai-lo-vit”", "because → “’cause” /kəz/ (informal)", "Pause a little before but and so."], "rtitle": "Three Movies, Three Opinions", "rsub": "The squad reviews Friday’s movies", "paras": ["Valeria · Comedy ⭐⭐⭐⭐⭐ — I think this movie is really funny! The actors are great and the story is about a crazy family, so it’s perfect for teens. I laugh a lot because the dog is the star!", "Leo · Action ⭐⭐⭐⭐ — It’s exciting and fast. The special effects are amazing, but the movie is a little too long — two and a half hours!", "Camila · Horror ⭐ — In my opinion, this movie is too scary and very boring. I don’t like horror movies, so I’m watching a comedy next time!"], "pull": "I don’t like horror movies, so I’m watching a comedy next time!", "atitle": "Read and answer.", "qa": ["1. Why does Valeria laugh a lot?", "2. What’s the problem with the action movie?", "3. What is Camila watching next time?"], "qb": ["4. Valeria thinks the comedy is funny. ____", "5. Leo thinks the action movie is too short. ____", "6. Camila gives the horror movie five stars. ____", "7. Camila doesn’t like horror movies. ____"], "ansR": {"1": "because the dog is the star", "2": "It’s too long (two and a half hours).", "3": "a comedy", "4": "T", "5": "F", "6": "F", "7": "T"}, "write": {"model_title": "Read Leo’s final project.", "meta": "Final project · Book 1 · All About Me — Leo", "model": "Hi! I’m Leo. I’m fourteen and I’m Dominican. I live in Santiago with my parents and my sister. I can play baseball very well, but I can’t sing! I always get up at 5:30 because I go to practice. Right now, I’m writing my final project. English is difficult, but I love it, so I study every day!", "useful": [["Me", "I’m… I live in… I have…"], ["Abilities", "I can… but I can’t…"], ["Routine", "I always / usually… because…"], ["Now & opinion", "Right now, I’m… I think English is…"]], "task_title": "Write your final project: All About Me", "task": "Write 60–80 words. Include:", "cells": ["1 · Who I am: name, age, nationality, family", "2 · My life: abilities, routine, likes", "3 · Now + opinion: present continuous + I think… + connectors"]}}];
